-- Vérification : plats mis à jour (23 attendus) et nombre d'options.
select category, name, jsonb_array_length(supplements) as options
  from menu_items
 where restaurant_id = (select id from restaurants where slug = 'baoma')
   and jsonb_array_length(supplements) > 0
 order by category, sort_order;
